"""ARENA u02 的 10 道测验（沿用旧版）"""
from unitlib import Q
QUIZ = [
  Q('反向传播 (backpropagation) 算法要解决的核心问题是什么？', ['决定网络应该有多少层', '高效地算出代价函数对所有参数的偏导数（梯度）', '把训练数据分成小批', '选择合适的激活函数'], 1, '梯度下降需要梯度，反向传播是**计算梯度**的高效算法。它本身不负责更新参数——更新参数是梯度下降（优化器）的事。'),
  Q('设 $C = f(a)$，$a = g(z)$，$z = h(w)$。按链式法则，$\\dfrac{\\partial C}{\\partial w}$ 等于？', ['$\\dfrac{\\partial C}{\\partial a} + \\dfrac{\\partial a}{\\partial z} + \\dfrac{\\partial z}{\\partial w}$', '$\\dfrac{\\partial C}{\\partial a}$', '$\\dfrac{\\partial C}{\\partial a}\\cdot\\dfrac{\\partial a}{\\partial z}\\cdot\\dfrac{\\partial z}{\\partial w}$', '$\\dfrac{\\partial z}{\\partial w}$'], 2, '链式法则是各段导数**相乘**，不是相加。$w$ 推动 $z$，$z$ 推动 $a$，$a$ 推动 $C$，影响逐段相乘。'),
  Q('对 $z = w\\,a^{(L-1)} + b$，$\\dfrac{\\partial z}{\\partial w}$ 等于？', ['$a^{(L-1)}$', '$w$', '$b$', '$1$'], 0, '$z$ 对 $w$ 是线性的，系数就是 $a^{(L-1)}$。这说明：上一层神经元越亮，调它对应的权重效果越明显。'),
  Q('同样对 $z = w\\,a^{(L-1)} + b$，$\\dfrac{\\partial z}{\\partial b}$ 等于？', ['$w$', '$a^{(L-1)}$', '$0$', '$1$'], 3, '$b$ 直接加在 $z$ 上，系数是 1。所以偏置的梯度就等于 $\\partial C / \\partial z$ 本身。'),
  Q('为什么叫「反向」传播？', ['因为它把训练数据倒过来喂给网络', '因为它从输出层开始往前算，每一层复用后一层算好的导数', '因为它让代价函数变大', '因为它随机打乱参数的顺序'], 1, '先算出代价对输出层的导数，再用链式法则一层层往前推。复用后一层的结果，是它高效的关键。'),
  Q('上一层的神经元 $a^{(L-1)}_k$ 连接着下一层的多个神经元。计算 $\\partial C / \\partial a^{(L-1)}_k$ 时要怎么做？', ['只看权重最大的那条连接', '取所有路径影响的平均值', '它对代价没有影响，结果为 0', '把经过下一层每个神经元的所有路径的影响加起来'], 3, "$a_k$ 通过每一个下一层神经元影响代价，总影响是各条路径之和：$\\sum_j w_{jk}\\,\\sigma'(z_j)\\,\\partial C/\\partial a_j$。"),
  Q('**小批量随机梯度下降 (mini-batch SGD)** 每一步怎么算梯度？', ['用随机抽取的一小批训练样本估计梯度', '用全部训练样本精确计算梯度', '只用一个固定的样本', '不算梯度，随机调整参数'], 0, '每一步只用一小批（比如 100 个）样本，得到一个有噪声但大致正确的梯度估计。每步快得多，整体收敛通常也更快。'),
  Q('Sigmoid 导数的最大值是多少？这对深层网络意味着什么？', ['1，不会造成问题', '0.5，梯度会变大', '0.25，反向传播时逐层相乘会让梯度越来越小（梯度消失）', '没有最大值'], 2, "$\\sigma'(z)=\\sigma(z)(1-\\sigma(z))$，最大值在 $z=0$ 处为 $0.25$。很多层连乘后梯度指数级变小，前面的层几乎学不动。"),
  Q('和「每次改动一个参数、重新跑一遍网络」相比，反向传播计算全部梯度的代价大约是？', ['和参数个数成正比，每个参数跑一遍', '只是一次前向计算的常数倍', '需要参数个数的平方次计算', '无法计算全部参数的梯度'], 1, '反向传播只需要一次前向 + 一次反向，总计算量是前向计算的常数倍（通常两三倍），和参数个数无关。这正是深度学习能训练几十亿参数模型的基础。'),
  Q('单个样本的代价 $C_0 = (a^{(L)} - y)^2$，那么 $\\dfrac{\\partial C_0}{\\partial a^{(L)}}$ 等于？', ['$(a^{(L)} - y)^2$', '$a^{(L)} - y$', '$2y$', '$2(a^{(L)} - y)$'], 3, '对 $(a-y)^2$ 求导得 $2(a-y)$。这是反向传播的「起点」：输出离目标越远，往回传的信号越强。'),
]
